    data = {"a": ["hello", "hello", "hi chatgpt"], "b": [3, 1, 3]}
    df = pd.DataFrame.from_dict(data)

    even_bs = []
    for i in range(len(data['b'])):
        if i % 2 == 0:
            d = df.loc[i, 'b']  # Use loc for label-based indexing
            even_bs.append(d)
    return df
```

